CREATE TEMP TABLE observations_fts_v21_ids AS SELECT id FROM observations_fts; DROP TABLE observations_fts; CREATE VIRTUAL TABLE observations_fts USING fts5(id UNINDEXED,title,topic_key,type,content); INSERT INTO observations_fts(id,title,topic_key,type,content) SELECT o.id,o.title,COALESCE(o.topic_key,''),o.type,o.content FROM observations o JOIN observations_fts_v21_ids f ON f.id=o.id; DROP TABLE observations_fts_v21_ids;
